-- +goose Up
-- A migration waits at most 5s for a lock and runs at most 60s, so it fails rather than stalls.
SET lock_timeout = '5s';
SET statement_timeout = '60s';

-- The Prompt set versions 1 and 2, imported as published versions from the repository's history
-- (version 1 from commit de6f134, version 2 from the code before the Prompt set moved to the
-- database). Version 1's supplier questions are of the buyer intent product. The scopes keep the
-- ids answers record: Twente, the Netherlands and Germany are a language with a region; Dutch,
-- German and English have none. Every question keeps its prompt id, so stored answers stay linked.
-- Version 2's questions carry their English translation. ON CONFLICT DO NOTHING lets it run again
-- without harm; 118 rows are far inside the time limits.
ON CONFLICT (id) DO NOTHING;

ON CONFLICT (version) DO NOTHING;

ON CONFLICT (version, prompt_id) DO NOTHING;
